import React, {useState, useCallback, useEffect} from 'react';
import axios from 'axios';
import './BestLocations.css';
import GoogleMapReact from 'google-map-react';
export default function BestLocations(){
    const[currentLatitude, setCurrentLatitude] =useState(null);
    const[currentLongitude, setCurrentLongitude] =useState(null);
    const [nearestLocations, setNearestLocations] = useState([]);
    const [locationNames, setLocationNames] = useState([]);
    const [locationDistances, setLocationDistances] = useState([]);
    const fetchLocation = useCallback(async ()=>{
        navigator.geolocation.getCurrentPosition(function (position){
            setCurrentLatitude(position.coords.latitude);
            setCurrentLongitude(position.coords.longitude);
        }, ()=>{
            console.log("Couldn't get current location");
        })
    },)

    async function fetchNearestLocations(){
        try{
            const response = await axios.get(`https://services.swpc.noaa.gov/json/ovation_aurora_latest.json`);
            var coordinatesArr = response.data.coordinates;

            coordinatesArr= filterArr(coordinatesArr);
            coordinatesArr= coordinatesArr.sort(sortFunction);
            var tenNearestLocations = coordinatesArr.slice(0,10);
            tenNearestLocations = tenNearestLocations.sort(sortByNearest);
            setNearestLocations(tenNearestLocations);
            const location_names = new Array(10);
            const distances = new Array(10);
            findLocationNamesAndDistances(tenNearestLocations, location_names, distances);
        }

        catch(error){
            console.error(error);
        }
    }

    function sortFunction(a, b) {
        if(a[2]==b[2]){
            return 0;
        }

        else if(a[2]<b[2]){
            return 1;
        }
        else{
            return -1;
        }
    };

    function filterArr(arr){
        const filteredArr =[];

        for(let i=0; i<arr.length; i++) {
            if (getDistance(arr[i])<2000){
                filteredArr.push(arr[i]);
            }
        }

        return filteredArr;
    }
    function getDistance(a){
            const currentlatitude = degrees_to_radians(currentLatitude);
            const currentlongitude = degrees_to_radians(currentLongitude);
            var a_lon = degrees_to_radians(a[0]-180);
            var a_lat = degrees_to_radians(a[1]);
            var distance= Math.acos((Math.sin(currentlatitude)*Math.sin(a_lat))+(Math.cos(currentlatitude)*Math.cos(a_lat)*Math.cos(a_lon-currentlongitude)))*6371;
            return distance;
    }

    async function findLocationNamesAndDistances(locationArr, locationNames, distances){

        for(let i=0; i<locationArr.length; i++){
            var lat = locationArr[i][1];
            var lon = locationArr[i][0]-180;
            distances[i]=Math.round(getDistance(locationArr[i]));
            try{
                const response = await axios.get(`http://api.openweathermap.org/geo/1.0/reverse?lat=${lat}&lon=${lon}&limit=5&appid=a8eb5aa64568880f32d4b8f8d32e1a9d`);
                if(response.data.length>0){
                    locationNames[i]=response.data[0].name + ", " + response.data[0].country;
                }

            }

            catch(error){
                console.error(error);
            }

        }
        setLocationNames(locationNames);
        setLocationDistances(distances);
    }
    function sortByNearest(a, b) {
        const currentlatitude = degrees_to_radians(currentLatitude);
        const currentlongitude = degrees_to_radians(currentLongitude);

        const a_lon = degrees_to_radians(a[0]-180);
        const b_lon = degrees_to_radians(b[0]-180);
        const a_lat = degrees_to_radians(a[1]);
        const b_lat = degrees_to_radians(b[1]);
        const distanceA= Math.acos((Math.sin(currentlatitude)*Math.sin(a_lat))+(Math.cos(currentlatitude)*Math.cos(a_lat)*Math.cos(a_lon-currentlongitude)))*6371;
        const distanceB= Math.acos((Math.sin(currentlatitude)*Math.sin(b_lat))+(Math.cos(currentlatitude)*Math.cos(b_lat)*Math.cos(a_lon-currentlongitude)))*6371;

        if(distanceA==distanceB){
            return 0;
        }

        else if(distanceA>distanceB){
            return 1;
        }
        else{
            return -1;
        }
    }

    function degrees_to_radians(degrees)
    {
    var pi = Math.PI;
    return degrees * (pi/180);
    }

    useEffect(()=>{
        fetchLocation();
    }, [])

    useEffect(()=>{
        fetchNearestLocations();
    },[])


    const defaultProps={
        center:{
            lat:10.99,
            lng:77.05
        },

        zoom:11
    };


    return (
        <div id="nearestLocation-page">
        <GoogleMapReact
            defaultCenter={defaultProps.center} 
            defaultZoom={defaultProps.zoom} 
            id="map">
        </GoogleMapReact>
        {/* <div class="nearestLocations">
            {
                nearestLocations.map((location, i) =>{
                    return (
                        <div key={i} id="location">
                            <section id="location-title">
                                <section id="city-name">
                                    {locationNames[i]}
                                </section>
                                <section id="distance">
                                    {locationDistances[i]} km away
                                </section>
                            </section>
                            <section id="aurora-percentage">
                                {location[2]}
                            </section>
                        </div>
                    )
                })
            }
        </div> */}

       </div>
    )
}
